/**
 * Built-in agent avatars (VI v1.0 §6): 16 characters × 8 agent hues, served as
 * SVG from `public/agent-avatars/<character>-<hue>.svg`. Generated by
 * docs/brand/botcord-vi/scripts/avatars.py — keep both lists in sync with it and
 * with backend/hub/agent_avatars.py. Order matters for hashing: append only.
 */

export const AGENT_AVATAR_CHARACTERS = [
  "robot", "alien", "ufo", "astronaut", "handheld", "slime", "octopus", "cat",
  "ghost", "jellyfish", "dinosaur", "bird", "chef", "wizard", "knight", "dj",
] as const;

export const AGENT_AVATAR_HUES = [
  "coral", "amber", "lime", "green", "cyan", "blue", "violet", "pink",
] as const;

export type AgentAvatarCharacter = (typeof AGENT_AVATAR_CHARACTERS)[number];
export type AgentAvatarHue = (typeof AGENT_AVATAR_HUES)[number];

/** Base colour of each hue, for colour swatches (matches --bc-agent-*). */
export const AGENT_AVATAR_HUE_COLORS: Record<AgentAvatarHue, string> = {
  coral: "#C25D58",
  amber: "#B46D10",
  lime: "#7E8814",
  green: "#3B9555",
  cyan: "#03919D",
  blue: "#3A84CA",
  violet: "#8071C8",
  pink: "#AF609F",
};

export function agentAvatarUrl(character: AgentAvatarCharacter, hue: AgentAvatarHue): string {
  return `/agent-avatars/${character}-${hue}.svg`;
}

export const AGENT_AVATAR_URLS: string[] = AGENT_AVATAR_CHARACTERS.flatMap((character) =>
  AGENT_AVATAR_HUES.map((hue) => agentAvatarUrl(character, hue)),
);

const AVATAR_URL_PATTERN = /^\/agent-avatars\/([a-z]+)-([a-z]+)\.svg$/;

export function parseAgentAvatarUrl(
  value: string | null | undefined,
): { character: AgentAvatarCharacter; hue: AgentAvatarHue } | null {
  const match = typeof value === "string" ? AVATAR_URL_PATTERN.exec(value) : null;
  if (!match) return null;
  const [, character, hue] = match;
  if (
    !(AGENT_AVATAR_CHARACTERS as readonly string[]).includes(character) ||
    !(AGENT_AVATAR_HUES as readonly string[]).includes(hue)
  ) {
    return null;
  }
  return { character: character as AgentAvatarCharacter, hue: hue as AgentAvatarHue };
}

export function isAgentAvatarUrl(value: string | null | undefined): value is string {
  return parseAgentAvatarUrl(value) !== null;
}
